const nextAgentTaskForHost = `-- name: NextAgentTaskForHost :one
UPDATE agent_task
SET status = 'leased', lease_expires_at = now() + $2::interval,
    attempts = attempts + 1, updated_at = now(),
    started_at = coalesce(started_at, now())
WHERE id = (
    SELECT t.id FROM agent_task t
    WHERE t.deployed_object_id = $1
      AND t.status NOT IN ('done', 'ignored')
      AND (
        t.ad_hoc
        OR t.step_index = (
          SELECT MIN(t2.step_index) FROM agent_task t2
          WHERE t2.deployed_object_id = $1
            AND NOT t2.ad_hoc
            AND t2.status NOT IN ('done', 'ignored')
        )
      )
    ORDER BY t.ad_hoc DESC, t.step_index
    LIMIT 1
)
AND (status = 'pending' OR (status = 'leased' AND lease_expires_at < now()))
RETURNING id, deployed_object_id, step_index, command, payload, status, lease_expires_at, attempts, output, last_error, created_at, updated_at, ignore_errors, ad_hoc, reboots, started_at, finished_at, max_attempts, milestone, step_script, wait_for
`

type NextAgentTaskForHostParams struct {
	DeployedObjectID pgtype.UUID     `json:"deployed_object_id"`
	Column2          pgtype.Interval `json:"column_2"`
}

// get-task: which task the host should run next. There are two lanes:
//
//   - Ad-hoc tasks (ad_hoc = true: operator `run` and scheduled dispatch) are
//     ALWAYS eligible and take priority. They must run even when an authored
//     step has terminally failed and stopped the deploy -- that is exactly when
//     an operator needs to run commands on the box to debug why a step failed.
//     A failed authored step no longer blocks them.
//
//   - Authored steps (ad_hoc = false) keep strict ordered semantics: the lowest
//     not-done/ignored step (an ignore_errors step that failed terminally is
//     'ignored' -- terminal, non-blocking, so the sequence steps past it), and
//     the sequence stops on a 'failed' step. This is "finish step N before N+1."
//
// The inner subquery picks the single highest-priority runnable candidate:
// any ad-hoc row, or the lowest not-done AUTHORED step, ordered ad-hoc-first
// then by step_index. The outer UPDATE then only commits if THAT SPECIFIC row
// is pending or its lease expired -- the candidate and the lease gate are
// evaluated on the SAME row (an earlier version filtered pending-or-expired
// before picking the lowest step_index, so a step an agent was genuinely
// working on went invisible and the NEXT step got leased instead -- a real bug
// caught by a second get-task while step 0 was still leased returning step 1).
// A non-leasable candidate matches 0 rows (ErrNoRows, "nothing to do right
// now"), so the agent finishes its current task before being handed another,
// and a failed authored step with no ad-hoc work pending correctly yields
// nothing.
//
// No FOR UPDATE SKIP LOCKED: there's only ever one live candidate row per host,
// so plain UPDATE's own row-level locking serializes two concurrent callers.
func (q *Queries) NextAgentTaskForHost(ctx context.Context, arg NextAgentTaskForHostParams) (AgentTask, error) {
	row := q.db.QueryRow(ctx, nextAgentTaskForHost, arg.DeployedObjectID, arg.Column2)
	var i AgentTask
	err := row.Scan(
		&i.ID,
		&i.DeployedObjectID,
		&i.StepIndex,
		&i.Command,
		&i.Payload,
		&i.Status,
		&i.LeaseExpiresAt,
		&i.Attempts,
		&i.Output,
		&i.LastError,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.IgnoreErrors,
		&i.AdHoc,
		&i.Reboots,
		&i.StartedAt,
		&i.FinishedAt,
		&i.MaxAttempts,
		&i.Milestone,
		&i.StepScript,
		&i.WaitFor,
	)
	return i, err
}

const nextStepIndexForHost = `-- name: NextStepIndexForHost :one
SELECT COALESCE(MAX(step_index), -1) + 1 FROM agent_task WHERE deployed_object_id = $1
`

// Ad-hoc tasks (internal/api's tasks.go) append after whatever steps a
// host already has -- authored deploy-time steps if any exist, or
// previous ad-hoc commands -- rather than picking an index that could
// collide. COALESCE handles "no rows yet" (a host with no authored
// steps at all getting its first ad-hoc command).
func (q *Queries) NextStepIndexForHost(ctx context.Context, deployedObjectID pgtype.UUID) (int32, error) {
	row := q.db.QueryRow(ctx, nextStepIndexForHost, deployedObjectID)
	var column_1 int32
	err := row.Scan(&column_1)
	return column_1, err
}

const recordValidatorResult = `-- name: RecordValidatorResult :exec
INSERT INTO validator_result (agent_task_id, kind, args, passed, message)
VALUES ($1, $2, $3, $4, $5)
`

type RecordValidatorResultParams struct {
	AgentTaskID pgtype.UUID     `json:"agent_task_id"`
	Kind        string          `json:"kind"`
	Args        json.RawMessage `json:"args"`
	Passed      bool            `json:"passed"`
	Message     *string         `json:"message"`
}

// Not :one/RETURNING *: found live that Postgres
// requires SELECT on a table's columns for RETURNING to work, even on an
// INSERT the caller definitely has permission for -- laforge_gateway is
// deliberately INSERT-only on this table (see migrations/00004's own
// comment, and TestGatewayRoleCannotReadContent's real proof that it
// can't read agent_heartbeat/event either), so RETURNING * always failed
// with "permission denied," 100% of the time, for the only role that
// ever calls this. Undetected until this had a real caller at all.
func (q *Queries) RecordValidatorResult(ctx context.Context, arg RecordValidatorResultParams) error {
	_, err := q.db.Exec(ctx, recordValidatorResult,
		arg.AgentTaskID,
		arg.Kind,
		arg.Args,
		arg.Passed,
		arg.Message,
	)
	return err
}

const renewAgentTaskLease = `-- name: RenewAgentTaskLease :execrows
UPDATE agent_task SET lease_expires_at = now() + $1::interval, updated_at = now()
WHERE id = $2 AND deployed_object_id = $3 AND status = 'leased'
`

type RenewAgentTaskLeaseParams struct {
	Lease            pgtype.Interval `json:"lease"`
	ID               pgtype.UUID     `json:"id"`
	DeployedObjectID pgtype.UUID     `json:"deployed_object_id"`
}

// Heartbeat-driven lease renewal. The agent names the task it is still running
// on every heartbeat; extending that task's lease keeps a long step (anything
// past one lease, 60s by default) from expiring and being leased AGAIN, which
// ran the same script twice at once after a reconnect. Scoped to the agent's
// own object and to a task that is still 'leased', so a stale or forged id
// changes nothing.
func (q *Queries) RenewAgentTaskLease(ctx context.Context, arg RenewAgentTaskLeaseParams) (int64, error) {
	result, err := q.db.Exec(ctx, renewAgentTaskLease, arg.Lease, arg.ID, arg.DeployedObjectID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const stampRebootDurationsForHost = `-- name: StampRebootDurationsForHost :exec
UPDATE agent_task r
SET finished_at = nxt.started_at, updated_at = now()
FROM (
  SELECT r2.id AS reboot_id,
         (SELECT n.started_at FROM agent_task n
            WHERE n.deployed_object_id = r2.deployed_object_id
              AND n.step_index > r2.step_index
              AND n.started_at IS NOT NULL
            ORDER BY n.step_index
            LIMIT 1) AS started_at
  FROM agent_task r2
  WHERE r2.deployed_object_id = $1 AND r2.reboots = true AND r2.status = 'done'
) nxt
WHERE r.id = nxt.reboot_id
  AND nxt.started_at IS NOT NULL
  AND (r.finished_at IS NULL OR r.finished_at < nxt.started_at)
`

// Make a reboot step's duration cover the WHOLE reboot. The agent acks a reboot
// 'done' BEFORE rebooting (durable completion -- see CompleteLeasedRebootsTaskForHost
// and the agent's reboot branch), so its finished_at lands at the ack (~seconds)
// and the real downtime (shutdown + boot + agent reconnect) hides in the gap
// before the next step is leased. Pull that gap in: set the reboot step's
// finished_at to the next step that actually started (its started_at IS the
// reconnect moment, since steps lease strictly in order and the next one can't
// start until the agent is back). Keyed on a fixed timestamp, not now(), so it's
// idempotent and converges -- safe to run on every get-task. Only ever EXTENDS
// (finished_at < next start), never shrinks, and a reboot with no later started
// step (last step, or next step blocked/failed) keeps its ack-time finish.
func (q *Queries) StampRebootDurationsForHost(ctx context.Context, deployedObjectID pgtype.UUID) error {
	_, err := q.db.Exec(ctx, stampRebootDurationsForHost, deployedObjectID)
	return err
}

